    V L_b;
    V L_before;
    V L_grave;
    V L_made;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:旗帜僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("一大波僵尸")})})}}));
    L_grave = m_zdeploy(Args{L_b, SV("zombie:脑光墓碑"), V(20.0)});
    L_before = [&]() -> V { V out_ = V::set(); V L_u; { V it1_ = py::iter_list(pvz::getattr(L_b, SY("units"))); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_u = it1_.idx(int64_t(i1_)); py::set_add(out_, L_u); }}return out_; }();
    (void)(m_zdeploy(Args{L_b, SV("zombie:旗帜僵尸"), V(22.0)}));
    L_made = [&]() -> V { V out_ = V::list(); V L_u; { V it2_ = py::iter_list((py::set_it(pvz::getattr(L_b, SY("units"))) - L_before)); for (size_t i2_ = 0; i2_ < it2_.len(); ++i2_) { L_u = it2_.idx(int64_t(i2_)); out_.append(rd(rd(pvz::getattr(L_b, SY("units")), L_u), SV("card_id"))); }}return out_; }();
