V C_DamageTests::m_hit(const Args& A) {
    V L_b = A.get(0, SY("b"), nullptr, "hit");
    V L_z = A.get(1, SY("z"), nullptr, "hit");
    V L_amount = (A.size() > 2 || A.has_kw(SY("amount"))) ? A.get(2, SY("amount"), nullptr) : V(V(10.0));
    V L_before;
    V L_index;
    L_before = rdm(L_z, &Obj::血量, SV("血量"));
    L_index = py::next([&]() -> V { V out_ = V::list(); V L_i; V L_other; { V it1_ = py::iter_list(rdm(pvz::getattr(L_b, SY("g")), &Obj::僵尸, SV("僵尸"))); const double st1_ = 0.0; for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_i = V(st1_ + double(i1_)); L_other = it1_.idx(int64_t(i1_)); if (!(py_is(L_other, L_z))) continue; out_.append(L_i); }}return out_; }());
    { V as2_ = L_index;
      pvz::setitem(pvz::getattr(L_b, SY("g")), SV("l"), as2_);
      pvz::setitem(pvz::getattr(L_b, SY("g")), SV("z"), as2_);
    }
    {
      py::WithGuard wg3_(callm(pvz::getattr(L_b, SY("targets")), SY("context"), Args{SV("zombie"), SV("plant"), SV("plants"), py_dict({{SV("_pvp_owner"), SV("plant")}, {SV("方向"), V(1.0)}})}));
        (void)((rd(pvz::getattr(L_b, SY("g")), SV("伤害僵尸"))).call(Args{L_index, V(1.0), L_amount}));
    }
    return (L_before - rdm(L_z, &Obj::血量, SV("血量")));
    return V::none();
}

V C_DamageTests::m_test_crowd_reduction_counts_neighbours_and_caps(const Args& A) {
    V L_b;
    V L_crowd;
    V L_lone;
    V L_z;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:普通僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("三五成群")})})}}));
    L_crowd = [&]() -> V { V out_ = V::list(); V L_i; { V it1_ = py::iter_list(py::range((int64_t)(V(7.0)).num())); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_i = it1_.idx(int64_t(i1_)); out_.append(m_zombie(Args{L_b, SV("zombie:普通僵尸"), (V(15.0) + (L_i * V(0.3)))})); }}return out_; }();
    { V it2_ = py::iter_list(L_crowd);
    for (size_t i2_ = 0; i2_ < it2_.len(); ++i2_) {
        L_z = it2_.idx(int64_t(i2_)); 
        setm(L_z, &Obj::血量, SV("血量"), V(1000.0));
    }}
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(0.0)}));
    (void)(m_assertAlmostEqual(Args{V(0.25), rd(rd(L_crowd, V(0.0)), SV("_pvp_zs_crowd_factor"))}));
    (void)(m_assertAlmostEqual(Args{V(2.5), m_hit(Args{L_b, rd(L_crowd, V(0.0))})}));
    L_lone = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:普通僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("三五成群")})})}}));
    L_z = m_zombie(Args{L_lone, SV("zombie:普通僵尸"), V(15.0)});
    setm(L_z, &Obj::血量, SV("血量"), V(1000.0));
    (void)(callm(pvz::getattr(L_lone, SY("zsecrets")), SY("step"), Args{V(0.0)}));
    (void)(m_assertAlmostEqual(Args{V(10.0), m_hit(Args{L_lone, L_z})}));
    return V::none();
}

V C_DamageTests::m_test_crowd_counts_across_the_ring_seam(const Args& A) {
    V L_b;
    V L_cols;
    V L_left;
    V L_right;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:普通僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("三五成群")})})}}));
    L_cols = py::int_(floordiv(pvz::getattr(L_b, SY("width")), pvz::getattr(L_b, SY("tile"))));
    L_left = m_zombie(Args{L_b, SV("zombie:普通僵尸"), V(0.5)});
    L_right = m_zombie(Args{L_b, SV("zombie:普通僵尸"), (L_cols - V(1.0))});
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(0.0)}));
    (void)(m_assertAlmostEqual(Args{V(0.85), py::m_get(L_left, SV("_pvp_zs_crowd_factor"), V(1.0))}));
    (void)(m_assertAlmostEqual(Args{V(0.85), py::m_get(L_right, SV("_pvp_zs_crowd_factor"), V(1.0))}));
    return V::none();
}

V C_DamageTests::m_test_crowd_single_neighbour_counted_once_on_narrow_maps(const Args& A) {
    V L_a;
    V L_b;
    V L_c;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:普通僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("三五成群")})})}}));
    pvz::setattr(L_b, SY("width"), (pvz::getattr(L_b, SY("tile")) * V(10.0)));
    L_a = m_zombie(Args{L_b, SV("zombie:普通僵尸"), V(2.0)});
    L_c = m_zombie(Args{L_b, SV("zombie:普通僵尸"), V(3.0)});
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(0.0)}));
    (void)(m_assertAlmostEqual(Args{V(0.85), rd(L_a, SV("_pvp_zs_crowd_factor"))}));
    return V::none();
}

V C_DamageTests::m_test_newspaper_rage_halves_damage(const Args& A) {
    V L_b;
    V L_full;
    V L_z;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:报纸僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("阿姆斯特朗")})})}}));
    L_z = m_zombie(Args{L_b, SV("zombie:报纸僵尸"), V(15.0)});
    setm(L_z, &Obj::血量, SV("血量"), V(1000.0));
    (void)(m_assertTrue(Args{py::m_get_slot(L_z, &Obj::手持, SV("手持"))}));
    L_full = m_hit(Args{L_b, L_z});
    (void)(callm(L_z, SY("pop"), Args{SV("手持")}));
    (void)(m_assertAlmostEqual(Args{(L_full / V(2.0)), m_hit(Args{L_b, L_z})}));
    return V::none();
}

V C_DamageTests::m_test_giant_control_halved(const Args& A) {
    V L_b;
    V L_z;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:巨人僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("不可撼动")})})}}));
    L_z = m_zombie(Args({L_b, SV("zombie:巨人僵尸"), V(15.0)}, {{SY("hold"), V(false)}}));
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(0.0)}));
    setm(L_z, &Obj::眩晕, SV("眩晕"), V(1000.0));
    setm(L_z, &Obj::冰冻, SV("冰冻"), V(2500.0));
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(0.0)}));
    (void)(m_assertAlmostEqual(Args{V(500.0), rdm(L_z, &Obj::眩晕, SV("眩晕"))}));
    (void)(m_assertAlmostEqual(Args{V(1750.0), rdm(L_z, &Obj::冰冻, SV("冰冻"))}));
    return V::none();
}

