V C_EconomyAndAuraTests::m_test_brain_per_plant_kill(const Args& A) {
    V L_b;
    V L_before;
    V L_flower;
    L_b = m_lane(Args({}, {{SY("plants"), V::list({SV("plant:豌豆射手"), SV("plant:向日葵")})}, {SY("zombies"), V::list({pm_zombie_secret_catalog::f_key(Args{SV("脑光")})})}}));
    L_flower = m_place(Args{L_b, SV("plant:向日葵"), V(10.0)});
    L_before = rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("resource"));
    setm(L_flower, &Obj::植物血, SV("植物血"), V(0.0));
    (void)(callm(L_b, SY("_step_original"), Args{}));
    (void)(m_assertEqual(Args{(L_before + V(15.0)), rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("resource"))}));
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("on_plant_killed"), Args{L_flower}));
    (void)(m_assertEqual(Args{(L_before + V(15.0)), rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("resource"))}));
    return V::none();
}

V C_EconomyAndAuraTests::m_test_subsidy_halves_the_day_interval_on_an_empty_field(const Args& A) {
    V L_b;
    V L_gained;
    V L_name;
    V L_normal;
    V L_start;
    V L_subsidy;
    L_normal = m_lane(Args{});
    L_subsidy = m_lane(Args({}, {{SY("zombies"), V::list({pm_zombie_secret_catalog::f_key(Args{SV("补贴")})})}}));
    L_gained = py_dict({});
    { V it1_ = py::iter_list(V::tuple({V::tuple({SV("normal"), L_normal}), V::tuple({SV("subsidy"), L_subsidy})}));
    for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) {
        { V ut2_ = py::as_seq(it1_.idx(int64_t(i1_))); L_name = ut2_.idx(0); L_b = ut2_.idx(1); } 
        L_start = rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("resource"));
        (void)(m_steps(Args{L_b, (V(30.0) * V(25.0))}));
        pvz::setitem(L_gained, L_name, (rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("resource")) - L_start));
    }}
    (void)(m_assertEqual(Args{(rd(L_gained, SV("normal")) * V(2.0)), rd(L_gained, SV("subsidy"))}));
    return V::none();
}

V C_EconomyAndAuraTests::m_test_heal_and_taco_from_the_holder_dave(const Args& A) {
    V L_b;
    V L_speed;
    V L_z;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:普通僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("生生不息")}), pm_zombie_secret_catalog::f_key(Args{SV("玉米卷")})})}}));
    L_z = m_zombie(Args{L_b, SV("zombie:普通僵尸"), V(26.0)});
    setm(L_z, &Obj::血量, SV("血量"), V(10.0));
    L_speed = rdm(L_z, &Obj::移速, SV("移速"));
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(12.0)}));
    (void)(m_assertGreater(Args{rdm(L_z, &Obj::血量, SV("血量")), V(10.0)}));
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(8.0)}));
    (void)(m_assertAlmostEqual(Args{(L_speed * V(2.0)), rdm(L_z, &Obj::移速, SV("移速"))}));
    (void)(callm(pvz::getattr(L_b, SY("zsecrets")), SY("step"), Args{V(20.0)}));
    (void)(m_assertAlmostEqual(Args{(L_speed * V(2.0)), rdm(L_z, &Obj::移速, SV("移速"))}));
    return V::none();
}

