V C_EconomyAndAuraTests::m_test_flock_surcharge_and_one_crow_per_scarecrow(const Args& A) {
    V L_b;
    V L_before;
    V L_col;
    V L_crows;
    V L_units;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:稻草人"), SV("zombie:乌鸦"), pm_zombie_secret_catalog::f_key(Args{SV("鸦群")})})}}));
    { V it1_ = py::iter_list(V::tuple({V(18.0), V(22.0)}));
    for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) {
        L_col = it1_.idx(int64_t(i1_)); 
        (void)(m_zdeploy(Args{L_b, SV("zombie:稻草人"), L_col}));
    }}
    L_before = rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("resource"));
    L_units = py::set_it(pvz::getattr(L_b, SY("units")));
    (void)(m_zdeploy(Args({L_b, SV("zombie:乌鸦"), V(20.0)}, {{SY("row"), V(8.0)}})));
    L_crows = [&]() -> V { V out_ = V::list(); V L_u; { V it2_ = py::iter_list((py::set_it(pvz::getattr(L_b, SY("units"))) - L_units)); for (size_t i2_ = 0; i2_ < it2_.len(); ++i2_) { L_u = it2_.idx(int64_t(i2_)); if (!((rd(rd(pvz::getattr(L_b, SY("units")), L_u), SV("card_id")) == SV("zombie:乌鸦")))) continue; out_.append(L_u); }}return out_; }();
    (void)(m_assertEqual(Args{V(3.0), py::len(L_crows)}));
    (void)(m_assertEqual(Args{(rd(pm_catalog::f_actual_card(Args{SV("zombie:乌鸦")}), SV("cost")) + V(100.0)), (L_before - rd(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("resource")))}));
    return V::none();
}

