V C_SelectedGraveTests::m_hit(const Args& A) {
    V L_b = A.get(0, SY("b"), nullptr, "hit");
    V L_grave = A.get(1, SY("grave"), nullptr, "hit");
    V L_amount = (A.size() > 2 || A.has_kw(SY("amount"))) ? A.get(2, SY("amount"), nullptr) : V(V(10.0));
    return V::func([](const Args& A) -> V {
    V L_self = A.get(0, SY("self"), nullptr, "hit");
    V L_b = A.get(1, SY("b"), nullptr, "hit");
    V L_z = A.get(2, SY("z"), nullptr, "hit");
    V L_amount = (A.size() > 3 || A.has_kw(SY("amount"))) ? A.get(3, SY("amount"), nullptr) : V(V(10.0));
    V L_before;
    V L_index;
    L_before = rdm(L_z, &Obj::血量, SV("血量"));
    L_index = py::next([&]() -> V { V out_ = V::list(); V L_i; V L_other; { V it1_ = py::iter_list(rdm(pvz::getattr(L_b, SY("g")), &Obj::僵尸, SV("僵尸"))); const double st1_ = 0.0; for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_i = V(st1_ + double(i1_)); L_other = it1_.idx(int64_t(i1_)); if (!(py_is(L_other, L_z))) continue; out_.append(L_i); }}return out_; }());
    { V as2_ = L_index;
      pvz::setitem(pvz::getattr(L_b, SY("g")), SV("l"), as2_);
      pvz::setitem(pvz::getattr(L_b, SY("g")), SV("z"), as2_);
    }
    {
      py::WithGuard wg3_(callm(pvz::getattr(L_b, SY("targets")), SY("context"), Args{SV("zombie"), SV("plant"), SV("plants"), py_dict({{SV("_pvp_owner"), SV("plant")}, {SV("方向"), V(1.0)}})}));
        (void)((rd(pvz::getattr(L_b, SY("g")), SV("伤害僵尸"))).call(Args{L_index, V(1.0), L_amount}));
    }
    return (L_before - rdm(L_z, &Obj::血量, SV("血量")));
return V::none(); }).call(Args{self_v(), L_b, L_grave, L_amount});
    return V::none();
}

V C_SelectedGraveTests::m_test_selection_needs_the_secret(const Args& A) {
    V L_b;
    V L_grave;
    L_b = m_lane(Args{});
    L_grave = m_zdeploy(Args{L_b, SV("zombie:脑光墓碑"), V(20.0)});
    (void)(m_assertIn(Args{SV("解除封印"), m_cmd(Args({L_b, SV("zombie"), SV("select_grave")}, {{SY("grave"), rdm(L_grave, &Obj::_pvp_id, SV("_pvp_id"))}}))}));
    return V::none();
}

V C_SelectedGraveTests::m_test_selected_grave_takes_a_quarter_and_never_stacks(const Args& A) {
    V L_a;
    V L_b;
    V L_c;
    V L_early;
    V L_g;
    V L_g1;
    V L_g2;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({pm_zombie_secret_catalog::f_key(Args{SV("解除封印")})})}, {SY("producer_protection_seconds"), V(0.0)}}));
    L_a = m_zdeploy(Args{L_b, SV("zombie:脑光墓碑"), V(20.0)});
    L_c = m_zdeploy(Args{L_b, SV("zombie:脑光墓碑"), V(24.0)});
    { V it1_ = py::iter_list(V::tuple({L_a, L_c}));
    for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) {
        L_g = it1_.idx(int64_t(i1_)); 
        setm(L_g, &Obj::血量, SV("血量"), V(1000.0));
    }}
    (void)(m_assertEqual(Args{SV(""), m_cmd(Args({L_b, SV("zombie"), SV("select_grave")}, {{SY("grave"), rdm(L_a, &Obj::_pvp_id, SV("_pvp_id"))}}))}));
    (void)(m_assertAlmostEqual(Args{V(2.5), m_hit(Args{L_b, L_a})}));
    (void)(m_assertAlmostEqual(Args{V(10.0), m_hit(Args{L_b, L_c})}));
    (void)(m_assertEqual(Args{SV(""), m_cmd(Args({L_b, SV("zombie"), SV("select_grave")}, {{SY("grave"), rdm(L_c, &Obj::_pvp_id, SV("_pvp_id"))}}))}));
    (void)(m_assertAlmostEqual(Args{V(10.0), m_hit(Args{L_b, L_a})}));
    (void)(m_assertAlmostEqual(Args{V(2.5), m_hit(Args{L_b, L_c})}));
    L_early = m_lane(Args({}, {{SY("zombies"), V::list({pm_zombie_secret_catalog::f_key(Args{SV("解除封印")})})}, {SY("producer_protection_seconds"), V(600.0)}}));
    L_g1 = m_zdeploy(Args{L_early, SV("zombie:脑光墓碑"), V(20.0)});
    L_g2 = m_zdeploy(Args{L_early, SV("zombie:脑光墓碑"), V(24.0)});
    { V as2_ = V(1000.0);
      setm(L_g1, &Obj::血量, SV("血量"), as2_);
      setm(L_g2, &Obj::血量, SV("血量"), as2_);
    }
    (void)(m_assertEqual(Args{SV(""), m_cmd(Args({L_early, SV("zombie"), SV("select_grave")}, {{SY("grave"), rdm(L_g1, &Obj::_pvp_id, SV("_pvp_id"))}}))}));
    (void)(m_assertAlmostEqual(Args{V(2.5), m_hit(Args{L_early, L_g1})}));
    (void)(m_assertAlmostEqual(Args{V(2.5), m_hit(Args{L_early, L_g2})}));
    return V::none();
}

V C_SelectedGraveTests::m_test_deploying_through_a_grave_selects_it(const Args& A) {
    V L_b;
    V L_grave;
    L_b = m_lane(Args({}, {{SY("zombies"), V::list({SV("zombie:普通僵尸"), pm_zombie_secret_catalog::f_key(Args{SV("解除封印")})})}}));
    L_grave = m_zdeploy(Args{L_b, SV("zombie:脑光墓碑"), V(20.0)});
    (void)(m_zdeploy(Args({L_b, SV("zombie:普通僵尸"), V(20.0)}, {{SY("grave"), rdm(L_grave, &Obj::_pvp_id, SV("_pvp_id"))}})));
    (void)(m_assertEqual(Args{rdm(L_grave, &Obj::_pvp_id, SV("_pvp_id")), py::m_get(rd(pvz::getattr(L_b, SY("players")), SV("zombie")), SV("selected_grave"))}));
    return V::none();
}

